  FOREIGN KEY (instance_id, current_revision_id) REFERENCES cognition_belief_revisions(instance_id, id) DEFERRABLE INITIALLY DEFERRED,
  CHECK ((object_ref IS NOT NULL) + (literal IS NOT NULL) = 1)
