  CHECK (valid_to IS NULL OR (valid_from IS NOT NULL AND valid_from <= valid_to)),
  UNIQUE (instance_id, id),
  FOREIGN KEY (instance_id) REFERENCES identity_instances(id) DEFERRABLE INITIALLY DEFERRED,
