CREATE TRIGGER current_perception_observations_insert BEFORE INSERT ON perception_observations BEGIN
SELECT RAISE(ABORT,'revision belongs to another object') WHERE EXISTS(SELECT 1 FROM perception_observation_revisions WHERE id=NEW.current_revision_id AND (observation_id<>NEW.id OR instance_id<>NEW.instance_id));
