CREATE TRIGGER goal_batch_initial BEFORE INSERT ON goal_activation_batches WHEN NEW.state<>'draft' BEGIN
SELECT RAISE(ABORT,'create batch in draft');
END;

CREATE TRIGGER goal_batch_finalize BEFORE UPDATE ON goal_activation_batches WHEN OLD.state='draft' AND NEW.state='finalized' BEGIN
SELECT RAISE(ABORT,'invalid goal distribution') WHERE
 (SELECT count(*) FROM goal_activation_records WHERE decision_batch_id=NEW.id)=0 OR
 abs((SELECT total(probability) FROM goal_activation_records WHERE decision_batch_id=NEW.id)-1)>0.000001 OR
 (SELECT total(selected) FROM goal_activation_records WHERE decision_batch_id=NEW.id)<1;
END;

CREATE TRIGGER goal_batch_no_unseal BEFORE UPDATE ON goal_activation_batches WHEN OLD.state='finalized' AND NEW.state<>'finalized' BEGIN
SELECT RAISE(ABORT,'cannot reopen goal batch');
END;

CREATE TRIGGER sealed_goal_batch_insert BEFORE INSERT ON goal_activation_records WHEN EXISTS(SELECT 1 FROM goal_activation_batches WHERE id=NEW.decision_batch_id AND state='finalized') BEGIN
SELECT RAISE(ABORT,'finalized goal batch immutable');
END;

CREATE TRIGGER sealed_goal_batch_update BEFORE UPDATE ON goal_activation_records WHEN EXISTS(SELECT 1 FROM goal_activation_batches WHERE id=NEW.decision_batch_id AND state='finalized') OR EXISTS(SELECT 1 FROM goal_activation_batches WHERE id=OLD.decision_batch_id AND state='finalized') BEGIN
SELECT RAISE(ABORT,'finalized goal batch immutable');
END;

CREATE TRIGGER sealed_goal_batch_delete BEFORE DELETE ON goal_activation_records WHEN EXISTS(SELECT 1 FROM goal_activation_batches WHERE id=OLD.decision_batch_id AND state='finalized') BEGIN
SELECT RAISE(ABORT,'finalized goal batch immutable');
END;

CREATE TRIGGER acyclic_evidence_derivations_insert BEFORE INSERT ON evidence_derivations BEGIN
SELECT RAISE(ABORT,'cycle detected') WHERE NEW.derived_evidence_id=NEW.parent_evidence_id OR EXISTS(
WITH RECURSIVE reach(node) AS (SELECT NEW.parent_evidence_id UNION SELECT e.parent_evidence_id FROM evidence_derivations e JOIN reach r ON e.derived_evidence_id=r.node WHERE e.id<>NEW.id)
SELECT 1 FROM reach WHERE node=NEW.derived_evidence_id);
END;

