END;

CREATE TRIGGER validate_goal_transitions BEFORE INSERT ON goal_transitions BEGIN
SELECT RAISE(ABORT,'invalid state transition') WHERE NOT ((NEW.from_state='candidate' AND NEW.to_state IN ('accepted','cancelled','expired')) OR (NEW.from_state='accepted' AND NEW.to_state IN ('active','paused','cancelled','expired')) OR (NEW.from_state='active' AND NEW.to_state IN ('paused','completed','cancelled','expired','failed')) OR (NEW.from_state='paused' AND NEW.to_state IN ('active','cancelled','expired','failed'))) OR NOT EXISTS(SELECT 1 FROM goal_items p WHERE p.id=NEW.goal_id AND p.instance_id=NEW.instance_id AND p.state=NEW.from_state AND NEW.transition_no=p.state_revision+1);
END;

CREATE TRIGGER apply_goal_transitions AFTER INSERT ON goal_transitions BEGIN
UPDATE goal_items SET state=NEW.to_state,state_revision=NEW.transition_no WHERE id=NEW.goal_id AND instance_id=NEW.instance_id;
END;

CREATE TRIGGER guard_goal_items BEFORE UPDATE ON goal_items WHEN NEW.state<>OLD.state OR NEW.state_revision<>OLD.state_revision BEGIN
SELECT RAISE(ABORT,'state changes require transition record') WHERE NEW.state_revision<>OLD.state_revision+1 OR NOT EXISTS(SELECT 1 FROM goal_transitions t WHERE t.goal_id=NEW.id AND t.instance_id=NEW.instance_id AND t.transition_no=NEW.state_revision AND t.from_state=OLD.state AND t.to_state=NEW.state);
END;

