CREATE TRIGGER immutable_value_profiles_delete BEFORE DELETE ON value_profiles WHEN NOT EXISTS(SELECT 1 FROM deletion_effects e JOIN deletion_requests r ON r.id=e.request_id WHERE e.object_ref=OLD.id AND e.instance_id=OLD.instance_id AND e.operation IN ('redact','purge') AND r.state='cleaning') BEGIN
SELECT RAISE(ABORT,'revision immutable; append a correction or authorized deletion');
END;

CREATE TRIGGER version_identity_identity_anchors BEFORE UPDATE ON identity_anchors WHEN NEW.anchor_object_id<>OLD.anchor_object_id OR NEW.version<>OLD.version BEGIN
SELECT RAISE(ABORT,'version ownership is immutable');
END;

