CREATE VIRTUAL TABLE memory_search USING fts5(
 content, memory_id UNINDEXED, instance_id UNINDEXED,
 content='memory_revisions', content_rowid='rowid', tokenize='unicode61'
);

CREATE TRIGGER fts_memory_insert AFTER INSERT ON memory_revisions BEGIN
INSERT INTO memory_search(rowid,content,memory_id,instance_id) VALUES(NEW.rowid,NEW.content,NEW.memory_id,NEW.instance_id);
END;

CREATE TRIGGER fts_memory_delete AFTER DELETE ON memory_revisions BEGIN
INSERT INTO memory_search(memory_search,rowid,content,memory_id,instance_id) VALUES('delete',OLD.rowid,OLD.content,OLD.memory_id,OLD.instance_id);
END;

CREATE TRIGGER fts_memory_update AFTER UPDATE ON memory_revisions BEGIN
INSERT INTO memory_search(memory_search,rowid,content,memory_id,instance_id) VALUES('delete',OLD.rowid,OLD.content,OLD.memory_id,OLD.instance_id); INSERT INTO memory_search(rowid,content,memory_id,instance_id) VALUES(NEW.rowid,NEW.content,NEW.memory_id,NEW.instance_id);
END;

